""" Count the number of edge pixels in the cluster. """
def countEdgePixels(pixels_dict: Any, rows: Any, cols: Any) -> object {
    dir_x = [-1, -1, 0, 1, 1, 1, 0, -1];
    dir_y = [0, 1, 1, 1, 0, -1, -1, -1];
    num_edge_pixels = 0;
    for X in pixels_dict.keys() {
        x = X % 256;
        y = X / 256;
        is_edge_pixel = False;
        for direction in range(8) {
            ny = y + dir_y[direction];
            nx = x + dir_x[direction];
            nX = (ny * cols) + nx;
            if (nX not in pixels_dict.keys()) {
                is_edge_pixel = True;
                break;
            }
        }
        if is_edge_pixel {
            num_edge_pixels += 1;
        }
    }
    return num_edge_pixels;
}

"""input desire lines, bit index and output the most common bit"""
def count_most(lines: Any, bit_idx: Any) -> object {
    count_bit = 0;
    for line in lines {
        if (line[bit_idx] == 1) {
            count_bit += 1;
        } else {
            count_bit -= 1;
        }
    }
    most_bit = 1 if (count_bit >= 0) else 0;
    return most_bit;
}

